from docx import Document
from docx.shared import Inches,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path
out=Path(r'docs/Guia_practica_historias_usuario_Plazoleta.docx'); d=Document(); s=d.sections[0]; s.top_margin=Inches(.68);s.bottom_margin=Inches(.68);s.left_margin=Inches(.78);s.right_margin=Inches(.78)
for n,z in [('Normal',10),('Title',22),('Heading 1',16),('Heading 2',12)]:
 st=d.styles[n];st.font.name='Calibri';st.font.size=Pt(z)
 if n!='Normal':st.font.bold=True;st.font.color.rgb=RGBColor(31,78,121)
d.styles['Normal'].paragraph_format.space_after=Pt(4)
def para(t='',style=None):return d.add_paragraph(t,style)
def section(title,obj,impl,show,check):
 d.add_heading(title,2);para('Qué busca. '+obj)
 para('Qué implementar.');
 for x in impl:d.add_paragraph(x,style='List Bullet')
 para('Qué hacer y mostrar en Swagger.');
 for x in show:d.add_paragraph(x,style='List Number')
 para('Comprueba también. '+check)
def table(h,rs):
 t=d.add_table(rows=1,cols=len(h));t.style='Table Grid';t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for i,x in enumerate(h):
  c=t.rows[0].cells[i];c.text=x;sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'D9EAF7');c._tc.get_or_add_tcPr().append(sh)
  for r in c.paragraphs[0].runs:r.bold=True
 for row in rs:
  cells=t.add_row().cells
  for i,x in enumerate(row):cells[i].text=x
 d.add_paragraph()
d.add_paragraph('Guía de implementación y demostración de historias de usuario',style='Title');para('Backend Plazoleta de Comidas · HU1–HU18')
para('Esta guía indica, para cada historia, qué parte del backend debes construir o revisar y qué pasos ejecutar para demostrarla. Sigue las operaciones y reglas registradas en el proyecto. Usa Swagger en Usuarios (http://localhost:8081/swagger-ui.html) y Plazoleta (http://localhost:8082/swagger-ui.html).')
d.add_heading('Antes de empezar',1)
for x in ['Inicia usuarios-service y plazoleta-service en terminales separadas con mvn spring-boot:run.','En Usuarios ejecuta POST /api/v1/auth/login para obtener token. Autoriza por separado Usuarios y Plazoleta con el token del rol que probarás. Cambia y vuelve a autorizar cada vez que cambies de usuario.','Crea y conserva los IDs de propietario, restaurante, plato, empleado, cliente y pedido. Las bases H2 guardan la información entre reinicios.','Para HU1, HU2, HU3, HU6 y HU8 usa correo, documento y NIT nuevos: el sistema exige unicidad. No incluyas tokens en capturas.']:d.add_paragraph(x,style='List Bullet')
para('El administrador inicial documentado es admin@plazoleta.local / Admin123!, salvo que se hayan cambiado INITIAL_ADMIN_EMAIL o INITIAL_ADMIN_PASSWORD.')
d.add_heading('HU1–HU9 Usuarios, restaurante, platos y listado',1)
section('HU1 Crear propietario','Un administrador registra un usuario PROPIETARIO.','Implementa POST /api/v1/usuarios/propietarios en Usuarios con autorización de ADMINISTRADOR; valida correo/documento únicos, documento numérico, celular hasta 13 caracteres y fecha válida para persona de 18 años o más; guarda la clave con BCrypt y fija rol PROPIETARIO.',['En Usuarios, autoriza el token ADMINISTRADOR y ejecuta POST /api/v1/usuarios/propietarios con datos nuevos y fecha de nacimiento de adulto.','Muestra respuesta con id, correo y rol PROPIETARIO; conserva el id para HU2.','Repite con fecha que indique menor de edad y muestra el rechazo.'],'También prueba correo o documento duplicado y acceso sin rol administrador.')
section('HU2 Crear restaurante','Un administrador registra un restaurante asignándole un propietario existente.','Implementa POST /api/v1/restaurantes en Plazoleta; valida NIT numérico y único, nombre que no sea solo números; consulta Usuarios por GET /internal/usuarios/{id} para confirmar que propietarioId existe y tiene rol PROPIETARIO; persiste la relación.',['Con ADMINISTRADOR en Plazoleta ejecuta POST /api/v1/restaurantes indicando nombre, NIT, dirección, teléfono, urlLogo y propietarioId creados en HU1.','Muestra el restaurante creado y que propietarioId coincide; conserva restauranteId para HU3 en adelante.','Intenta usar un id inexistente o que no sea PROPIETARIO y muestra que se rechaza.'],'Prueba el NIT duplicado. La llamada interna Plazoleta→Usuarios requiere X-Internal-Token; normalmente se demuestra por resultado de la operación pública, no invocando el endpoint interno.')
section('HU3 Crear plato','El propietario agrega un plato a su restaurante.','Implementa POST /api/v1/restaurantes/{restauranteId}/platos con autenticación PROPIETARIO; confirma que el token pertenece al dueño del restaurante; valida obligatorios y precio entero mayor que cero; guarda plato ligado al restaurante con activo=true.',['Autoriza Plazoleta con el token PROPIETARIO de HU1.','Envía POST con restauranteId y datos del plato: nombre, precio, descripción, urlImagen y categoría.','Muestra respuesta con restauranteId correcto y activo=true; guarda platoId.','Repite con precio cero o negativo y presenta el rechazo.'],'Comprueba que otro propietario no puede crear platos en ese restaurante.')
section('HU4 Modificar plato','El propietario actualiza solo el precio y la descripción del plato propio.','Implementa PATCH /api/v1/restaurantes/{restauranteId}/platos/{platoId}; autoriza dueño; limita el request a precio y descripción; no aceptes cambios a nombre, categoría, URL de imagen, restaurante ni activo.',['Con token propietario ejecuta PATCH en el restaurante/plato de HU3 con nuevo precio entero positivo y descripción.','Muestra precio y descripción nuevos. Compara nombre, categoría, urlImagen, restauranteId y activo antes/después para demostrar que siguen iguales.','Prueba precio no positivo y plato ajeno o restaurante incorrecto.'],'Enseña el estado del mismo recurso antes y después, no solo el código de respuesta.')
section('HU5 Iniciar sesión y usar JWT','Un usuario entra con correo y clave; el JWT identifica su rol y sirve en ambos microservicios.','Implementa POST /api/v1/auth/login; verifica la clave almacenada con BCrypt; genera JWT compartido por Usuarios y Plazoleta; aplica autorización por rol en las rutas protegidas.',['Inicia sesión con credenciales válidas y muestra tipo Bearer, correo, id y rol junto con token (oculta el valor completo en capturas).','Usa token de administrador en una acción administrativa permitida y token de cliente en GET /api/v1/restaurantes.','Inicia sesión con clave incorrecta y muestra 401. Con token de rol distinto intenta ruta protegida y muestra rechazo.'],'El botón Authorize se configura separadamente en los dos Swagger.')
section('HU6 Crear empleado','El propietario crea un empleado asociado a su restaurante.','Implementa POST /api/v1/restaurantes/{restauranteId}/empleados; verifica dueño; delega a Usuarios la creación con documento/correo únicos y clave cifrada; fija rol EMPLEADO y restauranteId; protege POST /internal/usuarios/empleados con X-Internal-Token.',['Con token del propietario llama la ruta de Plazoleta con datos de empleado y restauranteId.','Muestra id, correo, rol EMPLEADO y restauranteId asociados; luego inicia sesión con ese correo y clave en Usuarios y confirma el rol.','Intenta crear empleado para un restaurante ajeno o repetir correo/documento y muestra rechazo.'],'No llames endpoint interno desde Swagger público; verifica la integración desde la operación HU6.')
section('HU7 Cambiar estado de plato','El propietario activa o desactiva un plato propio.','Implementa PATCH /api/v1/restaurantes/{restauranteId}/platos/{platoId}/estado; valida propietario del restaurante y que plato pertenezca a él; modifica solo activo.',['Con propietario ejecuta la ruta de estado enviando activo=false.','Muestra respuesta del plato con activo=false. Ejecuta de nuevo con activo=true y muestra la reactivación.','Prueba plato que pertenece a otro restaurante y rol no autorizado.'],'Usa HU10 para comprobar después que un plato inactivo deja de aparecer en el menú.')
section('HU8 Registrar cliente','Una persona crea cuenta pública con rol CLIENTE.','Implementa POST /api/v1/usuarios/clientes sin JWT; valida campos requeridos y unicidad de correo/documento; fija rol CLIENTE sin permitir que el request lo elija; cifra clave con BCrypt.',['Ejecuta POST /api/v1/usuarios/clientes sin token con nombre, apellido, documento, celular, correo y clave nuevos.','Muestra rol CLIENTE en la respuesta e inicia sesión con la cuenta creada.','Repite con correo o documento duplicado y muestra conflicto.'],'Conserva clienteId y JWT para HU9–HU11, HU16 y HU17.')
section('HU9 Listar restaurantes','Un cliente consulta restaurantes paginados y ordenados por nombre ascendente.','Implementa GET /api/v1/restaurantes; permite solo CLIENTE; acepta page no negativo y size entre 1 y 100; ordena por nombre; responde cada restaurante con nombre/urlLogo más metadatos de página.',['Autoriza con token de cliente y llama GET /api/v1/restaurantes?page=0&size=10.','Muestra content con nombre y urlLogo, orden alfabético y page, size, totalElements y totalPages.','Consulta otra página y prueba page negativo o size fuera de 1–100.'],'Con token de otro rol demuestra denegación.')
d.add_heading('HU10–HU18 Menú y ciclo de pedidos',1)
section('HU10 Consultar menú','El cliente ve los platos activos de un restaurante, con filtro opcional y paginación.','Implementa GET /api/v1/restaurantes/{restauranteId}/platos; permite CLIENTE; filtra activo=true y opcionalmente categoría; pagina resultados.',['Con token CLIENTE ejecuta GET /api/v1/restaurantes/{restauranteId}/platos?page=0&size=10.','Muestra que el plato activo creado en HU3 aparece y la respuesta incluye metadatos de paginación.','Filtra con &categoria=Platos%20fuertes (ajusta al nombre exacto usado al crear); desactiva un plato con HU7 y vuelve a consultar para mostrar que ya no aparece.'],'Prueba restaurante inexistente y paginación inválida según reglas del API.')
section('HU11 Crear pedido','El cliente solicita platos y cantidades para un restaurante; el pedido inicia PENDIENTE.','Implementa POST /api/v1/pedidos para CLIENTE; valida restaurante, platos y cantidades positivas; verifica que los platos sean del restaurante; guarda pedido/items y estado PENDIENTE; evita más de un pedido activo por cliente (PENDIENTE, EN_PREPARACION o LISTO).',['Con cliente ejecuta POST /api/v1/pedidos con restauranteId y platos [{platoId, cantidad}].','Muestra id, clienteId, restauranteId, artículos, cantidades y estado PENDIENTE; conserva pedidoId.','Con el mismo cliente intenta crear otro antes de cerrar el primero y muestra rechazo.'],'Para volver a probar, termina el flujo HU13–HU15 o cancela mientras esté pendiente con HU16.')
section('HU12 Consultar bandeja','El empleado consulta pedidos del restaurante asociado, por estado opcional y paginados.','Implementa GET /api/v1/pedidos para EMPLEADO; limita al restaurante del empleado; acepta filtro estado y página/tamaño; devuelve metadatos.',['Con empleado creado en HU6 llama GET /api/v1/pedidos?estado=PENDIENTE&page=0&size=10.','Muestra pedido de HU11 y confirma que pertenece a su restaurante.','Consulta sin filtro de estado y prueba empleado de otro restaurante o rol incorrecto.'],'Usa un pedido pendiente disponible; los estados pueden cambiar a medida que avanzas el flujo.')
section('HU13 Asignarse e iniciar preparación','Un empleado toma un pedido e inicia preparación; queda asociado a su id.','Implementa PATCH /api/v1/pedidos/{pedidoId}/preparacion; valida empleado y restaurante; permite transición válida desde PENDIENTE; cambia a EN_PREPARACION y registra empleado asignado.',['Con empleado del restaurante ejecuta la ruta para el pedido pendiente.','Muestra estado EN_PREPARACION y empleadoAsignado con el id correcto.','Intenta repetir o usar pedido de otro restaurante y muestra rechazo.'],'El pedido creado en HU11 se usa después en HU14, HU15, HU17 y HU18.')
section('HU14 Marcar pedido listo','El empleado termina preparación y el sistema genera PIN para recoger el pedido.','Implementa PATCH /api/v1/pedidos/{pedidoId}/listo; permite transición desde EN_PREPARACION; cambia estado a LISTO; genera PIN de seis dígitos y lo devuelve en esta respuesta; registra aviso SMS simulado en consola.',['Con el mismo empleado ejecuta PATCH /api/v1/pedidos/{pedidoId}/listo.','Muestra estado LISTO y copia PIN de seis dígitos para HU15.','Muestra en consola [AVISO SMS LOCAL] y aclara que no se envía SMS real.'],'La respuesta que incluye PIN es la evidencia; no se incluye proveedor SMS en el proyecto.')
section('HU15 Entregar con PIN','El empleado entrega solo un pedido LISTO si el PIN coincide.','Implementa PATCH /api/v1/pedidos/{pedidoId}/entregar; exige empleado autorizado y PIN; permite solo LISTO; si PIN coincide cambia a ENTREGADO y registra actualización.',['Con empleado ejecuta la ruta y envía {"pinSeguridad":"PIN_RECIBIDO_EN_HU14"}.','Muestra respuesta con estado ENTREGADO.','Prueba PIN incorrecto y/o intentar entregar antes de LISTO; muestra que no cambia a ENTREGADO.'],'El PIN debe ser el real generado por HU14; no uses el ejemplo literal 123456.')
section('HU16 Cancelar pedido','El cliente cancela su propio pedido mientras permanezca PENDIENTE.','Implementa PATCH /api/v1/pedidos/{pedidoId}/cancelar para CLIENTE; verifica que sea dueño y estado PENDIENTE; registra estado cancelado según el modelo.',['Crea un pedido nuevo con cliente y deja estado PENDIENTE; ejecuta cancelar con su token.','Muestra nuevo estado y que el pedido no se puede preparar como pendiente.','En otro pedido inicia preparación con HU13 y luego intenta cancelarlo; muestra rechazo.'],'Solo el dueño puede cancelar; usa un segundo cliente para probar el límite de propiedad.')
section('HU17 Consultar trazabilidad','El cliente dueño consulta estados, fechas y observaciones asociadas a su pedido.','Implementa GET /api/v1/pedidos/{pedidoId}/trazabilidad; limita consulta al cliente dueño; devuelve las transiciones registradas con estado, usuarioId, fecha y observación.',['Con el cliente dueño llama la ruta para pedidoId tras avanzar por HU13 y HU14 o tras cancelar HU16.','Muestra los eventos y fechas que reflejan el recorrido efectuado.','Con otro cliente intenta consultar el mismo pedido y presenta la denegación.'],'Hazlo después de ejecutar transiciones; un pedido recién creado tendrá menos eventos que uno completado.')
section('HU18 Consultar eficiencia','El propietario revisa duración de pedidos entregados y ranking de duración promedio por empleado en su restaurante.','Implementa GET /api/v1/restaurantes/{restauranteId}/eficiencia para PROPIETARIO; valida pertenencia del restaurante; calcula duración de pedidos entregados y ordena ascendentemente promedios por empleado.',['Completa al menos un pedido por HU11–HU15 para generar datos de entrega.','Con el token propietario llama GET /api/v1/restaurantes/{restauranteId}/eficiencia.','Muestra duraciones y ranking ascendente; prueba restaurante ajeno y explica que sin pedidos entregados no habrá datos útiles.'],'Para comparar empleados, completa pedidos con más de un empleado cuando el escenario de prueba lo permita.')
d.add_heading('Orden sugerido para la demostración completa',1)
para('Crea propietario (HU1) → restaurante (HU2) → plato (HU3) → login y rol (HU5) → empleado (HU6) → cliente (HU8) → catálogo (HU9–HU10) → pedido (HU11) → bandeja (HU12) → preparación (HU13) → listo y PIN (HU14) → entrega (HU15) → trazabilidad (HU17) → eficiencia (HU18). Demuestra HU4 y HU7 como cambios de menú; HU16 con un pedido separado que siga PENDIENTE.')
d.add_heading('Qué guardar como evidencia',1)
for x in ['Una captura o registro por historia con endpoint, rol, datos usados y respuesta; tapa token, claves y datos personales.','Incluye un caso rechazado por la regla principal de la historia: edad, duplicado, rol, pertenencia, estado o PIN según corresponda.','Anota IDs usados para que otra persona pueda repetir la secuencia. No reutilices correo/documento/NIT al crear registros nuevos.','Códigos referenciales del proyecto: 401 autenticación/credenciales, 403 rol, 400 regla o dato inválido, 404 recurso inexistente/ajeno y 409 duplicado. Verifica el código concreto en la respuesta del API.']:d.add_paragraph(x,style='List Bullet')
para('Base de esta guía: matriz docs/HU1-HU9.md, flujo docs/guia-presentacion-HU1-HU18.md, README.md y rutas de los controladores REST.')
f=s.footer.paragraphs[0];f.alignment=WD_ALIGN_PARAGRAPH.CENTER;f.add_run('Plazoleta Backend · Implementación HU1–HU18  |  ');fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');f._p.append(fld)
d.save(out);print(out.resolve())
